// Copies the main site's shared look into the PHP blog, so blog/ stays a
// self-contained folder that can be deployed on its own (it is served at
// /insights/ next to the main site). Run with `npm run sync-blog`; `npm run b`
// runs it too. Generated files carry a "generated" note — edit the src/
// originals, not the copies.
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const SRC = path.join(ROOT, 'src');
const BLOG = path.join(ROOT, 'blog');

const copy = (from, to) => {
  fs.mkdirSync(path.dirname(path.join(BLOG, to)), { recursive: true });
  fs.copyFileSync(path.join(SRC, from), path.join(BLOG, to));
};

// ---- stylesheets, scripts, logos (same file names as in src/)
for (const f of ['fonts.css', 'main.css', 'site.css', 'demo.css']) copy(`styles/${f}`, `assets/css/${f}`);
for (const f of ['main.js', 'site.js']) copy(`js/${f}`, `assets/js/${f}`);
for (const f of ['gsap.min.js', 'ScrollTrigger.min.js', 'SplitText.min.js', 'lenis.min.js']) copy(`js/vendor/${f}`, `assets/js/vendor/${f}`);
for (const f of fs.readdirSync(path.join(SRC, 'assets/logos')).filter(f => f.endsWith('.svg'))) copy(`assets/logos/${f}`, `assets/logos/${f}`);
copy('assets/images/favicon.png', 'assets/img/favicon.png');

// ---- partials -> PHP. Blog pages live in one folder, so {{ base }} becomes "",
// which makes "assets/..." resolve to blog/assets/. Site links are already
// root-absolute ("/drivesense/", "/#faq"); links into the blog stay relative.
const note = '<?php /* Generated by scripts/sync-blog.js from src/partials/%s — edit that file, not this one. */ ?>\n';
function partial(name, out, locals = {}) {
  let s = fs.readFileSync(path.join(SRC, 'partials', name), 'utf8');
  s = s.replace(/\{\{\s*base\s*\}\}/g, '');
  for (const [k, v] of Object.entries(locals)) s = s.replace(new RegExp(`\\{\\{\\s*${k}\\s*\\}\\}`, 'g'), v);
  if (/\{\{/.test(s)) throw new Error(`${name}: unreplaced {{ }} placeholder`);
  // links to the blog itself, so they work wherever the blog folder is mounted
  s = s.replace(/href="\/insights\/"/g, 'href="index.php"').replace(/href="\/insights\/\?article=([a-z0-9-]+)"/g, 'href="article.php?slug=$1"');
  fs.writeFileSync(path.join(BLOG, 'partials', out), note.replace('%s', name) + s);
}
partial('nav.html', 'nav.php');
partial('footer.html', 'footer.php', { tagline: 'Insights · Field notes from the road, the floor and the shelf' });
partial('demo.html', 'demo.php');

console.log('blog synced from src/');
